@php use App\Infrastructure\Docker\Yaml; @endphp
# Generated by Mini Forge. Changes here are overwritten on the next provisioning.
name: mini-forge

x-logging: &logging
  driver: local
  options:
    max-size: "10m"
    max-file: "3"

services:
  # Traefik reads container labels through this proxy instead of the raw
  # Docker socket. It only allows GET on containers, events, version and
  # ping, so Traefik cannot start, stop or exec into anything.
  socket-proxy:
    image: {!! Yaml::string($socketProxyImage) !!}
    container_name: mini-forge-socket-proxy
    restart: unless-stopped
    environment:
      CONTAINERS: "1"
      EVENTS: "1"
      PING: "1"
      VERSION: "1"
      POST: "0"
    volumes:
      - /var/run/docker.sock:/var/run/docker.sock:ro
    networks: [socket]
    mem_limit: 64m
    logging: *logging

  traefik:
    image: {!! Yaml::string($traefikImage) !!}
    container_name: mini-forge-traefik
    restart: unless-stopped
    depends_on: [socket-proxy]
    command:
      - --providers.docker.endpoint=tcp://socket-proxy:2375
      # Only containers with traefik.enable=true are routed.
      - --providers.docker.exposedbydefault=false
      - {!! Yaml::string('--providers.docker.network='.$network) !!}
      - --entrypoints.web.address=:80
      - --entrypoints.web.http.redirections.entrypoint.to=websecure
      - --entrypoints.web.http.redirections.entrypoint.scheme=https
      - --entrypoints.websecure.address=:443
      - --entrypoints.websecure.http.tls.certresolver=letsencrypt
      - --entrypoints.websecure.http3=true
      - {!! Yaml::string('--certificatesresolvers.letsencrypt.acme.email='.$acmeEmail) !!}
      - --certificatesresolvers.letsencrypt.acme.storage=/letsencrypt/acme.json
      - --certificatesresolvers.letsencrypt.acme.httpchallenge.entrypoint=web
      # The dashboard and API stay off; ping serves the health check on the
      # internal port 8080, which is not published.
      - --api.dashboard=false
      - --ping=true
      - --log.level=WARN
    ports:
      - "80:80"
      - "443:443"
      - "443:443/udp"
    volumes:
      - letsencrypt:/letsencrypt
    networks: [socket, proxy]
    healthcheck:
      test: ["CMD", "traefik", "healthcheck", "--ping"]
      interval: 10s
      timeout: 5s
      retries: 3
      start_period: 10s
    mem_limit: 128m
    logging: *logging

networks:
  socket:
    internal: true
  proxy:
    name: {!! Yaml::string($network) !!}
    external: true

volumes:
  letsencrypt:
